#!/usr/bin/env bash
# Renders every picture at its real size, one after another, then leaves out/.done.
# On this machine (8 cores, Cycles on 6 of them) a scene takes 7 to 9 minutes at 96 samples and
# the hero about 10; the whole run is about an hour and a half.
# Do not edit this file while it runs: bash reads a script as it goes.
set -uo pipefail
here="$(cd "$(dirname "$0")" && pwd)"
for shot in hero hook charge absorb harden fade toss count join walk score; do
  "$here/run.sh" "$shot" - "${SAMPLES:-96}" 2>&1 | grep "saved\|rror"
done
for shot in piece-pawn piece-robot piece-slime piece-ghost; do
  "$here/run.sh" "$shot" - 96 2>&1 | grep "saved\|rror"
done
echo done > "$here/out/.done"
